import { useState, useRef, useEffect } from 'react'
import {
  ModalWrapper,
  Button,
  InputContainer,
  CustomCheckbox
} from './index.style'

function InterStateModal (props) {
  const {
    type,
    changeModal,
    handleUpload,
    requestData,
    endorsementData,
    handleSubmit,
    uploadedUrl
  } = props
  const [checked, setChecked] = useState(false)
  const [newPremi, setPremi] = useState('')
  const inputRef = useRef(null)
  const checkBoxChange = () => {
    setChecked(!checked)
  }
  const handleChangeInput = (e) => {
    setPremi(e.target.value)
  }
  useEffect(() => {
    if (checked) {
      inputRef.current.focus()
    } else setPremi('')
  }, [checked])
  return type ? (
    <ModalWrapper>
      <div className='content'>
        <img
          className='centerImg'
          src={
            type === 'accept'
              ? 'https://pp-img-prod.s3.ap-southeast-3.amazonaws.com/website/Icons/GreenTick.png'
              : 'https://pp-img-prod.s3.ap-southeast-3.amazonaws.com/website/Icons/Cross.png'
          }
        />
        <div className='textContainer'>
          <p className='header'>
            {type === 'accept'
              ? 'Approve this application?'
              : 'Reject this application?'}
          </p>
          {type === 'accept' ? (
            <p className='subHeader'>
              You can approve this application with or <br /> without adjusting
              the premium.
            </p>
          ) : (
            <p className='subHeader'>
              Are you sure you want to reject this application?
            </p>
          )}
        </div>
        {type === 'accept' && (
          <>
            <div className='horizontalBar' />
            <InputContainer checked={checked}>
              <div className='header'>
                <p className='text'>Current Premium</p>
                {checked && <p className='text'>New Premium</p>}
              </div>
              <div className='inputContainer'>
                {checked ? (
                  <div className='checkedInputContainer'>
                    <div className='greyInput input1 input3'>
                      IDR{' '}
                      {endorsementData?.premium
                        ? endorsementData.premium
                        : requestData?.premium}
                    </div>
                    <div className='input2 whiteBG input3'>
                      <p>IDR</p>
                      <input
                        ref={inputRef}
                        value={newPremi}
                        onChange={handleChangeInput}
                      />
                    </div>
                  </div>
                ) : (
                  <div className='input greyInput'>
                    IDR{' '}
                    {endorsementData?.premium
                      ? endorsementData.premium
                      : requestData?.premium}
                  </div>
                )}
              </div>
              <div className='checkbox-container'>
                <div>
                  <CustomCheckbox
                    onChange={checkBoxChange}
                    type='checkbox'
                    id='customCheckbox'
                    checked={checked}
                  />
                  <label htmlFor='customCheckbox' />
                </div>
                <p>Adjust Premium</p>
              </div>
            </InputContainer>
          </>
        )}
        <div className='horizontalBar' />
        <div className='uploadSection'>
          <p className='subHeader'>Approval Document</p>
          <label
            class='label-input'
            onChange={handleUpload}
            htmlFor='input-file'
          >
            <input name='input-file' type='file' id='input-file' hidden />
            <p>{uploadedUrl.slice(-35)}</p>
            <img
              src={
                'https://pp-img-prod.s3.ap-southeast-3.amazonaws.com/website/Icons/upload-small.svg'
              }
            />
          </label>
        </div>

        <div className='buttonSection'>
          <Button
            onClick={(e) => {
              e.stopPropagation()
              changeModal(null)
            }}
            type={'cancel'}
          >
            CANCEL
          </Button>
          <Button
            onClick={() => handleSubmit(type, newPremi, uploadedUrl)}
            type={type}
          >
            {type === 'accept' ? 'APPROVE' : 'REJECT'}
          </Button>
        </div>
      </div>
    </ModalWrapper>
  ) : null
}

export default InterStateModal
