import { ModalWrapper } from './index.style'
import InterStateModal from '../InterStateModal'
import FinalStateModal from '../FinalStateModal'
import InfoStateModal from '../InfoStateModal'

function Modal (props) {
  const {
    show: type,
    changeModal,
    handleUpload,
    requestData,
    endorsementData,
    handleSubmit,
    uploadedUrl
  } = props
  return type ? (
    <ModalWrapper
      onClick={() => {
        changeModal(null)
      }}
    >
      <div
        onClick={(e) => {
          e.stopPropagation()
        }}
        className='main-model'
      >
        {(type === 'accept' || type === 'reject') && (
          <InterStateModal
            type={type}
            changeModal={changeModal}
            handleUpload={handleUpload}
            requestData={requestData}
            handleSubmit={handleSubmit}
            uploadedUrl={uploadedUrl}
            endorsementData={endorsementData}
          />
        )}
        {(type === 'accepted' || type === 'rejected') && (
          <FinalStateModal
            type={type}
            changeModal={changeModal}
            handleUpload={handleUpload}
            handleSubmit={handleSubmit}
          />
        )}
        {(type === 'failed' || type === 'proceed') && (
          <InfoStateModal
            type={type}
            changeModal={changeModal}
            handleUpload={handleUpload}
            handleSubmit={handleSubmit}
          />
        )}
      </div>
    </ModalWrapper>
  ) : null
}

export default Modal
