import { ModalWrapper, Button } from './index.style'

function InfoStateModal ({ type, changeModal, handleUpload }) {
  return type ? (
    <ModalWrapper type={type}>
      <img
        className='bannerImg'
        src={
          type === 'failed'
            ? 'https://pp-img-prod.s3.ap-southeast-3.amazonaws.com/website/Icons/sad.svg'
            : 'https://pp-img-prod.s3.ap-southeast-3.amazonaws.com/website/Icons/timesand.svg'
        }
      />
      <div className='textContainer'>
        <p className='title'>
          {type === 'failed' ? 'Failed to Process' : 'Processing...'}
        </p>
        <p className='subtext1'>
          {type === 'failed'
            ? `We apologize that we were unable to process this due to an error. Please try again. Thank you.`
            : `Please wait and don’t close this page until our system complete the processing your data and document.`}
        </p>
        {type === 'failed' && (
          <div className='buttonSection'>
            <Button
              onClick={(e) => {
                e.stopPropagation()
                changeModal(null)
              }}
              type={'cancel'}
            >
              BACK
            </Button>
          </div>
        )}
      </div>
    </ModalWrapper>
  ) : null
}

export default InfoStateModal
