
import { ContainerLayout } from './index.style';

function Viwer({ header, type, url }) {
    const handleDownload = () => {
        fetch(url)
            .then(response => response.blob())
            .then(blob => {
                const filename = url.match(/\/([^/]+\.png)$/)[1];
                const newurl = window.URL.createObjectURL(new Blob([blob]));
                const link = document.createElement('a');
                link.href = newurl;
                link.setAttribute('download', filename || type);
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
            })
            .catch(error => console.error('Error downloading image:', error));
    };
    const handleClick = ()=>{
        if(type==="pdf"){
            window.open(url, '_blank', 'noreferrer');
        }
        else{
            handleDownload()
        }
    }
    return (
        <ContainerLayout>
            <div className='titleSec'>
                <p className='title'>{header}</p>
                <a onClick={handleClick} className='downloadSec'>
                    <p>DOWNLOAD</p>
                    <img src="https://pp-img-prod.s3.ap-southeast-3.amazonaws.com/website/Icons/Download.png" />
                </a>
            </div>
            <div className='Viwer'>
                {/* <Document
                file={{ url: "https://storage.googleapis.com/pp_static_insurance_docs_staging/Sertifikat_2992022.pdf" }}
            >
                <Page
                      pageNumber={1}
                      className='pdf-canvas'
                      renderTextLayer={false}
                />
            </Document> */}
                {type === "pdf" ?
                    <iframe
                        src={url}
                        title="PDF Viewer"
                        style={{ width: '100%', height: '100%', borderRadius: '16px' }}
                    >
                        <p>Failed to load PDF</p>
                    </iframe>
                    :
                    <img src={url} style={{ width: '100%', height: '100%', borderRadius: '16px' }} />
                }
            </div>
        </ContainerLayout>
    )
}

export default Viwer;
