import { useEffect, useState } from 'react'
import CustomerData from './components/CustomerData'
import Footer from './components/Footer'
import Modal from './components/Modal'
import { connect } from 'react-redux'
import { injectIntl } from 'react-intl'
import policyAction from '../../../redux/policy/actions'
import { Form } from 'antd'
import { useRouteMatch } from 'react-router'
import CircularLoader from '../../../components/CircularLoader'
import request from '../../../request/axios/endorsement'

const { resetReduxPolicy, tokenizedDetailEndorsement, authorisedEndorsement } =
  policyAction

function MoladinEndorsement (props) {
  const router = useRouteMatch()
  const {
    getPolicyEndorsementDetailResult,
    policyEndorsementDetailLoading,
    policyEndorsementLoading,
    policyEndorsement
  } = props

  const [showModel, setShowModal] = useState('')
  const [requestData, setRequestData] = useState(null)
  const [endorsementData, setEndorsementData] = useState(null)
  const [appNo, setAppNo] = useState('')
  const [uploadedUrl, setUploadedUrl] = useState('')
  const [currentType, setCurrentType] = useState(null)
  const changeModal = (val) => {
    setShowModal(val)
  }
  const handleUpload = async (e) => {
    const files = e?.target?.files
    const formData = new FormData()
    formData.append('file', files[0])
    const response = await request.postUploadFileRequest(formData)
    const res = response?.data
    if (res?.status === 'success') {
      setUploadedUrl(res?.data?.url)
    }
  }
  const handleSubmit = (type, premi, url) => {
    setCurrentType(type)
    const { token, id } = router.params
    const payload = {
      registration_status: type === 'accept' ? 'Accept' : 'Reject',
      acceptance_letter_url: type === 'accept' ? url : '-',
      rejection_letter_url: type === 'reject' ? url : '-'
    }
    if (type === 'accept') if (premi) payload.premium = parseInt(premi)
    props.authorisedEndorsement({
      query: {
        internal_id: id,
        token: token
      },
      body: payload
    })
  }

  //   const handleDownload = () => {
  //     fetch("https://pp-img-prod.s3.ap-southeast-3.amazonaws.com/website/Icons/Rejected.png")
  //       .then((response) => response.blob())
  //       .then((blob) => {
  //         const url = window.URL.createObjectURL(new Blob([blob]));
  //         const link = document.createElement("a");
  //         link.href = url;
  //         link.setAttribute("download", "image.png" || "image"); // Set the filename for download
  //         document.body.appendChild(link);
  //         link.click();
  //         document.body.removeChild(link);
  //       })
  //       .catch((error) => console.error("Error downloading image:", error));
  //   };

  const getRequestData = () => {
    const { id, token } = router.params
    const payload = {
      query: {
        id: id,
        token: token
      }
    }
    props.tokenizedDetailEndorsement(payload)
  }

  useEffect(() => {
    if (router?.params) {
      getRequestData()
    }
  }, [])

  useEffect(() => {
    if (policyEndorsement?.error) {
      setShowModal('failed')
    } else if (currentType) {
      changeModal(currentType + 'ed')
      setCurrentType(null)
      setUploadedUrl('')
      getRequestData()
    }
  }, [policyEndorsement])

  useEffect(() => {
    if (policyEndorsementLoading) {
      setShowModal('proceed')
    }
  }, [policyEndorsementLoading])

  useEffect(() => {
    if (
      getPolicyEndorsementDetailResult &&
      Object.keys(getPolicyEndorsementDetailResult).length > 0
    ) {
      setRequestData(getPolicyEndorsementDetailResult?.Request)
      setEndorsementData(getPolicyEndorsementDetailResult?.endorsement)
      setAppNo(getPolicyEndorsementDetailResult?.ApplicationNo)
    }
  }, [getPolicyEndorsementDetailResult])
  return (
    <div style={{ border: '0px #111 solid', borderTopWidth: '4px' }}>
      <CircularLoader
        isSpining={
          (policyEndorsementDetailLoading || policyEndorsementLoading) &&
          requestData
        }
      >
        <CustomerData requestData={requestData} appNo={appNo} />
        <Footer requestData={requestData} changeModal={changeModal} />
        <Modal
          handleUpload={handleUpload}
          handleSubmit={handleSubmit}
          changeModal={changeModal}
          show={showModel}
          requestData={requestData}
          endorsementData={endorsementData}
          uploadedUrl={uploadedUrl}
        />
        {/* <div onClick={handleDownload} className='print-label'>Label Cetak</div> */}
      </CircularLoader>
    </div>
  )
}
const MoladinEndorsementWrapped = Form.create()(MoladinEndorsement)

export default connect(
  (state) => ({
    getPolicyEndorsementDetailResult: state.Policy.tokenisedEndorsementDetail,
    policyEndorsementDetailLoading: state.Loading.TOKENIZED_ENDORSEMENT_DETAIL,
    policyEndorsementDetailError: state.Error.TOKENIZED_ENDORSEMENT_DETAIL,
    policyEndorsement: state.Policy.authorizedEndorsementData,
    policyEndorsementMessage: state.Policy.authorizedEndorsementDataMessage,
    policyEndorsementLoading: state.Loading.AUTHORIZED_ENDORSEMENT,
    policyEndorsementError: state.Error.AUTHORIZED_ENDORSEMENT
  }),
  {
    authorisedEndorsement,
    tokenizedDetailEndorsement,
    resetReduxPolicy
  }
)(injectIntl(MoladinEndorsementWrapped))
