import { ContainerLayout } from './index.style'
import Viwer from '../Viwer'
import SingleDataContainer from '../SingleData'
import moment from 'moment'
import { formatCurrency } from '../../../../../helpers/utility'

function CustomerData (props) {
  const { requestData, appNo } = props
  const isPDF = (filename) => {
    if (filename) return filename.toLowerCase().endsWith('.pdf')
  }
  return (
    <ContainerLayout>
      <div className='orderId'>Order ID : {appNo}</div>
      <div className='detailSection1'>
        <div className='header'>Data Pengajuan</div>
        <div className='pdfParent'>
          <Viwer
            type={isPDF(requestData?.insurance_form_url) ? 'pdf' : 'image'}
            url={requestData?.insurance_form_url}
            header={'Sequis Form'}
          />
          <Viwer
            type={isPDF(requestData?.riplay_form_url) ? 'pdf' : 'image'}
            url={requestData?.riplay_form_url}
            header={'Riplay Personal'}
          />
        </div>
      </div>
      <div className='detailSection2'>
        <SingleDataContainer
          type='1'
          title='Loan Amount'
          amount={formatCurrency(requestData?.amount, 'Rp')}
        />
        <SingleDataContainer
          type='1'
          title='Premium'
          amount={formatCurrency(requestData?.premium, 'Rp')}
        />
        <SingleDataContainer
          type='1'
          title='Start Date'
          amount={moment(requestData?.start_date).format('DD MMMM YYYY')}
        />
        <SingleDataContainer
          type='1'
          title='End Date'
          amount={moment(requestData?.end_date).format('DD MMMM YYYY')}
        />
      </div>
      <div className='horizontal-bar' />
      <div className='detailSection1'>
        <div className='header'>Data Pribadi</div>
        <div className='pdfParent'>
          <Viwer
            type={isPDF(requestData?.ktp_url) ? 'pdf' : 'image'}
            url={requestData?.ktp_url}
            header={'Photo ID / KTP'}
          />
          <Viwer
            type={isPDF(requestData?.npwp_url) ? 'pdf' : 'image'}
            url={requestData?.npwp_url}
            header={'Photo NPWP (optional)'}
          />
        </div>
      </div>
      <div className='detailSection2'>
        <SingleDataContainer
          type='2'
          title='ID Number'
          amount={requestData?.identity_no}
        />
        <SingleDataContainer
          type='2'
          title='Full Name'
          amount={requestData?.name}
        />
        <SingleDataContainer
          type='2'
          title='Date of Birth'
          amount={moment(requestData?.dob).format('DD MMMM YYYY')}
        />
        <SingleDataContainer
          type='2'
          title='Phone Number'
          amount={requestData?.phone_no}
        />
        <SingleDataContainer
          type='2'
          title='Email'
          amount={requestData?.email}
        />
      </div>
    </ContainerLayout>
  )
}

export default CustomerData
